16	package org.springframework.samples.petclinic.util;
17	
18	/**
19	 * Normalizes free-form telephone numbers into canonical <a
20	 * href="https://en.wikipedia.org/wiki/E.164">E.164</a> form (a leading {@code '+'} followed by
21	 * country code and national digits, e.g. {@code '+61412345678'}).
22	 *
23	 * <p>The rules, applied in order: strip spaces, dashes and brackets; keep an explicit leading
24	 * {@code '+'} and country code when present, otherwise assume country code {@code '+61'} and drop a
25	 * single leading {@code '0'} from the national digits; require 8 to 15 digits after the {@code '+'}.
26	 * A value that cannot satisfy these rules has no valid E.164 form.
27	 *
28	 * <p>This is the single source of truth shared by the inbound {@code TelephoneValidation}
29	 * constraint (which rejects numbers with no valid E.164 form) and {@code OwnerMapper} (which stores
30	 * the E.164 string), so a value that validates is exactly one that normalizes.
31	 */
32	public final class TelephoneNormalizer {
33	
34	    private static final String DEFAULT_COUNTRY_CODE = "61";
35	
36	    private TelephoneNormalizer() {
37	    }
38	
39	    /**
40	     * Convert a raw telephone number to its E.164 form, or return {@code null} when it has none.
41	     *
42	     * @param raw the inbound telephone number (may be {@code null})
43	     * @return the E.164 string (e.g. {@code '+61412345678'}), or {@code null} if {@code raw} is
44	     * {@code null} or cannot form a valid E.164 number
45	     */
46	    public static String toE164(String raw) {
47	        if (raw == null) {
48	            return null;
49	        }
50	        String trimmed = raw.trim();
51	        boolean hasCountryCode = trimmed.startsWith("+");
52	        String body = hasCountryCode ? trimmed.substring(1) : trimmed;
53	        String digits = body.replaceAll("[\\s()\\-]", "");
54	        if (digits.isEmpty() || !digits.matches("\\d+")) {
55	            return null;
56	        }
57	        String e164Digits;
58	        if (hasCountryCode) {
59	            e164Digits = digits;
60	        } else {
61	            String national = digits.startsWith("0") ? digits.substring(1) : digits;
62	            e164Digits = DEFAULT_COUNTRY_CODE + national;
63	        }
64	        if (e164Digits.length() < 8 || e164Digits.length() > 15) {
65	            return null;
66	        }
67	        return "+" + e164Digits;
68	    }
69	}
