99	    @ExceptionHandler(DuplicateTelephoneException.class)
100	    @ResponseBody
101	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
102	        logger.warn("Duplicate telephone at {} {}: {}",
