136	     * @param request {@link HttpServletRequest} object referring to the current request.
137	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
138	     */
139	    @ExceptionHandler(Exception.class)
140	    @ResponseBody
141	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
142	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
143	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
145	        return ResponseEntity.status(status).body(detail);
146	    }
