148	    /**
149	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
150	     * method returns a 404 Not Found status if an entity does not exist.
151	     *
152	     * @param e The {@link DataIntegrityViolationException} to be handled
153	     * @param request {@link HttpServletRequest} object referring to the current request.
154	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
155	     */
156	    @ExceptionHandler(DataIntegrityViolationException.class)
157	    @ResponseBody
158	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
159	        logger.warn("Data integrity violation at {} {}: {}",
160	            request.getMethod(),
161	            request.getRequestURI(),
162	            e.getMessage());
163	        logger.debug("Data integrity violation stacktrace", e);
164	        HttpStatus status = HttpStatus.NOT_FOUND;
165	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
166	        return ResponseEntity.status(status).body(detail);
167	    }
168	
169	    /**
170	     * Handles exception thrown by Bean Validation on controller methods parameters. The response
171	     * body carries an {@code errors} array naming each rejected field (e.g. a required field that
172	     * is missing or blank), alongside the detailed {@code schemaValidationErrors}.
173	     *
174	     * @param e The {@link MethodArgumentNotValidException} to be handled
175	     * @param request {@link HttpServletRequest} object referring to the current request.
176	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
177	     */
178	    @ExceptionHandler(MethodArgumentNotValidException.class)
179	    @ResponseBody
180	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
181	        HttpStatus status = HttpStatus.BAD_REQUEST;
182	        BindingErrorsResponse errors = new BindingErrorsResponse();
183	        BindingResult bindingResult = e.getBindingResult();
184	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
185	        if (bindingResult.hasErrors()) {
186	            errors.addAllErrors(bindingResult);
187	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
188	                .map(FieldError::getField)
189	                .distinct()
190	                .toList();
191	            detail.setProperty("errors", invalidFields);
192	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
193	                .map(fieldError -> {
194	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
195	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
196	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
197	                        fieldError.getField(),
198	                        defaultMessage,
199	                        rejectedValue);
200	                    return new ValidationMessageDto(message)
201	                        .putAdditionalProperty("field", fieldError.getField())
202	                        .putAdditionalProperty("rejectedValue", rejectedValue)
203	                        .putAdditionalProperty("defaultMessage", defaultMessage);
204	                })
205	                .toList();
206	            logger.debug("Validation error at {} {}: {}",
207	                request.getMethod(),
208	                request.getRequestURI(),
209	                bindingResult.getFieldErrors());
210	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
211	            return ResponseEntity.status(status).body(detail);
212	        }
213	        return ResponseEntity.status(status).body(detail);
214	    }
